    "topicTitle": "Figuras de linguagem e funções da linguagem",
    "stem": "[FUNECE/SEDUC-CE 2026 - Item Gramatical #587] Sob a perspectiva do padrão culto da Língua Portuguesa e do conteúdo \"Figuras de linguagem e funções da linguagem\", examine a seguinte assertiva: A função da linguagem em que o enunciador enfatiza o canal de comunicação para testar sua eficiência, manter ou interromper o contato com o interlocutor (ex.: \"Alô?\", \"Entende?\", \"Está ouvindo?\") denomina-se",
