    "topicCode": "Port.05",
    "topicTitle": "Ortografia oficial e acentuação gráfica (Acordo Ortográfico)",
    "stem": "[FUNECE/SEDUC-CE 2026 - Item Gramatical #670] Sob a perspectiva do padrão culto da Língua Portuguesa e do conteúdo \"Ortografia oficial e acentuação gráfica (Acordo Ortográfico)\", examine a seguinte assertiva: Assinale a opção em que todas as palavras estão correta e obrigatoriamente acentuadas pela regra das palavras PROPAROXÍTONAS.",
