    "topicTitle": "Emprego de tempos e modos verbais e concordância",
    "stem": "[FUNECE/SEDUC-CE 2026 - Item Gramatical #730] Sob a perspectiva do padrão culto da Língua Portuguesa e do conteúdo \"Emprego de tempos e modos verbais e concordância\", examine a seguinte assertiva: No que concerne à correlação verbal (harmonia entre tempos e modos verbais no período composto), assinale a frase que exemplifica a correlação correta de acordo com a norma-padrão.",
    "options": {
      "B": "Se a comissão examinadora revisasse o gabarito, os candidatos ficariam satisfeitos.",
      "C": "Se a escola puder contratar novos docentes, todos os horários seriam preenchidos.",
      "D": "Caso o aluno estudasse com dedicação diária, ele passará em primeiro lugar na prova.",
      "A": "Quando o edital saísse na próxima semana, os concurseiros farão inscrições imediatas."
    },
    "correct": "B",
    "explanation": "Gabarito Comentado: Letra B. A correlação clássica da oração condicional contrafactual exige: Pretérito Imperfeito do Subjuntivo (\"revisasse\") correlacionado com o Futuro do Pretérito do Indicativo (\"ficariam\"). (Item elaborado com rigor normativo conforme a tradição da banca FUNECE/CEV-UECE)."
