    "explanation": "Gabarito Comentado: Letra B. A sintaxe proíbe separar por vírgula termos imediatos da oração que mantêm vínculo estrutural direto: sujeito e predicado, verbo e seu complemento (objeto direto/indireto), nome e seu complemento nominal. (Item elaborado com rigor normativo conforme a tradição da banca FUNECE/CEV-UECE)."
